/**
 * Convert relative imports in src/pages/**/*.astro and src/layouts/*.astro
 * to use @/ path aliases.
 *
 * Patterns handled:
 * - `import X from "../foo"` \(1 level: src/pages/*.astro\)
 * - `import X from "../../foo"` \(2 levels: src/pages/components/*.astro\)
 * - `import X from "../../../foo"` \(3 levels: src/pages/examples/dashboard/*.astro\)
 * - `import "../styles/global.css"` \(side-effect CSS imports, no `from`\)
 * - Single and double quoted variants
 * - `import X from '../foo'` with single quotes
 *
 * For layout files \(src/layouts/*.astro\):
 * - `import "../styles/global.css"` -> `import "@/styles/global.css"`
 * - `import X from "../components/..."` -> `import X from "@/components/..."`
 * - `import X from "../scripts/..."` -> `import X from "@/scripts/..."`
 */

const fs = require\('fs'\);
const path = require\('path'\);

const PROJECT_ROOT = '/Users/denny/Dropbox/12-套件及腳手架/Frontend/cubby-ui';
const SRC_DIR = path.join\(PROJECT_ROOT, 'src'\);

// Recursively find all .astro files in a directory
function findAstroFiles\(dir\) {
  const results = [];
  for \(const entry of fs.readdirSync\(dir, { withFileTypes: true }\)\) {
    const fullPath = path.join\(dir, entry.name\);
    if \(entry.isDirectory\(\)\) {
      results.push\(...findAstroFiles\(fullPath\)\);
    } else if \(entry.isFile\(\) && entry.name.endsWith\('.astro'\)\) {
      results.push\(fullPath\);
    }
  }
  return results;
}

/**
 * For a given file, determine how many `../` segments are needed to reach `src/`.
 * E.g.:
 *   src/pages/index.astro           -> 1 \(../ reaches src/\)
 *   src/pages/components/btn.astro  -> 2 \(../../ reaches src/\)
 *   src/pages/examples/dashboard/x  -> 3 \(../../../ reaches src/\)
 *   src/layouts/Layout.astro        -> 1 \(../ reaches src/\)
 */
function getDepthToSrc\(filePath\) {
  const relToSrc = path.relative\(SRC_DIR, path.dirname\(filePath\)\);
  const segments = relToSrc.split\(path.sep\).filter\(Boolean\);
  return segments.length;
}

let totalFiles = 0;
let totalChanges = 0;

function processFile\(filePath\) {
  const content = fs.readFileSync\(filePath, 'utf-8'\);
  const depth = getDepthToSrc\(filePath\);
  const dotdotPrefix = '../'.repeat\(depth\);

  // Build escaped prefix for regex
  // "../" repeated `depth` times, e.g. "../../" for depth=2
  const escapedPrefix = dotdotPrefix
    .replace\(/\\./g, '\\\\.'\)
    .replace\(/\\//g, '\\\\/'\);

  // Match both:
  //   import Foo from "../../layouts/Layout.astro"
  //   import "../../styles/global.css"
  //   import Foo from '../../layouts/Layout.astro'
  // The optional group handles the `Identifier from` part
  const regex = new RegExp\(
    `\(import\\\\s+\(?:[\\\\w{}*\\\\s,]+\\\\s+from\\\\s+\)?\)\(["']\)${escapedPrefix}\([^"']+\)\\\\2`,
    'g'
  \);

  const relPath = path.relative\(PROJECT_ROOT, filePath\);
  const changes = [];

  const newContent = content.replace\(regex, \(match, importPart, quote, restPath\) => {
    const oldImport = `${quote}${dotdotPrefix}${restPath}${quote}`;
    const newImport = `${quote}@/${restPath}${quote}`;
    changes.push\({ old: oldImport, new: newImport }\);
    return `${importPart}${newImport}`;
  }\);

  if \(changes.length > 0\) {
    fs.writeFileSync\(filePath, newContent, 'utf-8'\);
    totalFiles++;
    totalChanges += changes.length;
    console.log\(`\\n--- ${relPath} \(${changes.length} import\(s\)\) ---`\);
    for \(const c of changes\) {
      console.log\(`  ${c.old}  =>  ${c.new}`\);
    }
  }
}

// Process src/pages/**/*.astro
const pagesDir = path.join\(SRC_DIR, 'pages'\);
const pageFiles = findAstroFiles\(pagesDir\);
pageFiles.sort\(\);
for \(const f of pageFiles\) {
  processFile\(f\);
}

