const layoutsDir = path.join\(SRC_DIR, 'layouts'\);
const layoutFiles = findAstroFiles\(layoutsDir\);
layoutFiles.sort\(\);
for \(const f of layoutFiles\) {
  processFile\(f\);
}

console.log\(`\\n========================================`\);
console.log\(`Done! ${totalFiles} files changed, ${totalChanges} imports converted.`\);
